import pandas as pd
from collections import Counter

def task_func(obj_list, attribute):
    # Return an empty DataFrame with the expected columns if no objects are provided.
    if not obj_list:
        return pd.DataFrame(columns=['attribute', 'count'])

    # Count the occurrences of the given attribute value in the object list.
    counts = Counter(getattr(obj, attribute) for obj in obj_list)

    # Build a DataFrame from the counter.
    df = pd.DataFrame({
        'attribute': list(counts.keys()),
        'count': list(counts.values())
    })

    return df

